struct Base1 { int x; };
struct Base2 { int y; };
struct Derived : Base1, Base2 {};

using PtmD = int Derived::*;
using PtmB1 = int Base1::*;

// Pointers targeting the same physical member (x)
PtmD p_dx = &Derived::x;
PtmB1 p_b1x = &Base1::x;

bool same_subobj = (p_dx == p_b1x); // true (Base->Derived conversion rules apply)

// Pointers targeting different physical members (x vs y)
PtmD p_dy = &Derived::y;

bool different_subobj = (p_dx == p_dy); // false (x and y are distinct)

// Comparison ensures both member and subobject alignment
// regardless of the intermediate type used for access.
